// Human-study dilemma library. Everything is drawn from window.LIBRARY (assets/library-data.js, generated by
// Cosmos_HumanDilemmas_Singer/build_library.py together with data/library.json); nothing is typed into the page.
// No network, no storage, no HTML injection. A recorded AI cell appears only if the generated file carries one
// (build_library.py merges one export_results.py file per model, from verified live ledgers only). Each model is shown
// on its own; no number anywhere combines models.
(function () {
  "use strict";
  var L = window.LIBRARY; if (!L) return;
  function $(id) { return document.getElementById(id); }
  function h(tag, cls, text) { var n = document.createElement(tag); if (cls) n.className = cls; if (text != null) n.textContent = text; return n; }
  function add(p) { for (var i = 1; i < arguments.length; i++) if (arguments[i]) p.appendChild(arguments[i]); return arguments[arguments.length - 1]; }
  function clear(n) { while (n.firstChild) n.removeChild(n.firstChild); return n; }
  function pct(x) { return Math.round(x * 100) + "%"; }
  function link(href, text) { var a = h("a", null, text); a.href = href; if (/^https?:/.test(href)) a.rel = "noopener"; return a; }
  function dl(box, rows) { rows.forEach(function (r) { if (r[1] == null || r[1] === "") return; add(box, h("dt", null, r[0])); var d = add(box, h("dd")); if (typeof r[1] === "string") d.textContent = r[1]; else add(d, r[1]); }); }

  var ITEMS = L.items, BY = {}; ITEMS.forEach(function (it) { BY[it.id] = it; });
  var STATUS = [["all", "All"], ["selected", "Selected at screening"], ["reserve", "Reserve (promise items)"], ["excluded", "Excluded"]];
  var ELIG = { planned: ["kind-ours", "Planned for our test"], reserve: ["kind-ours", "Reserve stratum, not planned"], stress_test: ["kind-stress", "Stress test only"],
               not_usable: ["kind-none", "Not usable"], excluded_a1: ["kind-none", "Excluded after the AI mapping screen"], characterisation: ["kind-none", "Not used: one-sided human choices"] };
  var CELL = { "orig": "Order 1, no priority", "swap": "Order 2, no priority", "other/orig": "Others first · order 1", "other/swap": "Others first · order 2",
               "self/orig": "Own first · order 1", "self/swap": "Own first · order 2" };
  var st = { status: "all", topic: "all", q: "", sel: null };

  // ---------------------------------------------------------------- filters
  function matches(it) {
    if (st.status !== "all" && it.screening.status !== st.status) return false;
    if (st.topic !== "all" && it.topic !== st.topic) return false;
    if (!st.q) return true;
    var t = [it.id, it.title, it.original.scenario, it.original.option_other_regarding, it.original.option_self_regarding, L.topics[it.topic]].join(" ").toLowerCase();
    return st.q.split(/\s+/).every(function (w) { return t.indexOf(w) >= 0; });
  }
  function drawChips() {
    var f = clear($("status-chips"));
    STATUS.forEach(function (s) {
      var n = ITEMS.filter(function (it) { return s[0] === "all" || it.screening.status === s[0]; }).length, b = add(f, h("button", "chip"));
      b.type = "button"; add(b, document.createTextNode(s[1])); add(b, h("span", "ct", "· " + n));
      b.setAttribute("aria-pressed", st.status === s[0] ? "true" : "false"); b.setAttribute("data-status", s[0]);
      b.addEventListener("click", function () {
        var i = Array.prototype.indexOf.call(f.children, b), had = document.activeElement === b;
        st.status = s[0]; drawChips(); drawList();
        if (had) f.children[i].focus();
      });
    });
  }
  var tsel = $("topic"); add(tsel, h("option", null, "All topics")).value = "all";
  Object.keys(L.topics).forEach(function (k) { add(tsel, h("option", null, L.topics[k])).value = k; });
  tsel.addEventListener("change", function () { st.topic = tsel.value; drawList(); });
  $("q").addEventListener("input", function () { st.q = $("q").value.trim().toLowerCase(); drawList(); });

  function drawList() {
    var box = clear($("list")), shown = ITEMS.filter(matches);
    shown.forEach(function (it) {
      var b = add(box, h("button", "dcard")); b.type = "button"; b.setAttribute("data-id", it.id); b.setAttribute("data-status", it.screening.status);
      b.setAttribute("aria-pressed", st.sel === it.id ? "true" : "false");
      add(b, h("small", null, it.id + " · " + L.topics[it.topic])); add(b, document.createTextNode(it.title));
      var e = ELIG[it.eligibility]; add(b, h("span", "kind " + e[0], e[1]));
      b.addEventListener("click", function () { open(it.id, true); });
    });
    $("count").textContent = "Showing " + shown.length + " of " + ITEMS.length + " dilemmas";
    $("empty").hidden = shown.length > 0;
  }

  // ---------------------------------------------------------------- detail
  function open(id, focus) {
    var it = BY[id]; if (!it) return;
    st.sel = id; drawList();
    if (location.hash !== "#" + id) history.replaceState(null, "", "#" + id);
    $("detail").hidden = false;
    ["r1", "r2", "r3", "r4"].forEach(function (r) { $(r).removeAttribute("aria-current"); }); $("r2").setAttribute("aria-current", "step");
    $("d-h").textContent = "2 · " + it.title;
    $("d-meta").textContent = "EMCS item " + it.item_no + " · " + L.topics[it.topic] + " · socially " + it.social_closeness + " protagonist";
    var o = it.original;
    $("o-scn").textContent = o.scenario;
    var opts = clear($("o-opts"));
    [["Other-regarding option (Singer: altruistic)", o.option_other_regarding], ["Self-regarding option (Singer: egoistic)", o.option_self_regarding]].forEach(function (x) {
      var c = add(opts, h("div", "optc")); add(c, h("span", "cls", x[0])); add(c, document.createTextNode(x[1]));
    });
    var attr = clear($("o-attr"));
    add(attr, document.createTextNode("Source: EMCS Scale, S1 Table of " + L.source.citation + " "));
    add(attr, link(L.source.doi_url, L.source.doi_url)); add(attr, document.createTextNode(". Licensed "));
    add(attr, link(L.source.licence_url, L.source.licence_short)); add(attr, document.createTextNode(", © 2019 Singer et al. Shown verbatim; our adaptation is shown separately. " + o.option_order_note));
    $("o-lang").textContent = L.language_caveat;

    var H = it.human;
    $("h-ctx").textContent = L.human_data_note + " A person who states a priority is asking for the option that fits it, whatever most participants chose.";
    var bars = clear($("h-bars"));
    [["Chose the other-regarding option", H.share_other_regarding], ["Chose the self-regarding option (100% minus the published share)", H.share_self_regarding_derived]].forEach(function (x) {
      var r = add(bars, h("div", "share")); add(r, h("span", "lab", x[0]));
      var tr = add(r, h("div", "track")); tr.setAttribute("role", "img"); tr.setAttribute("aria-label", x[0] + ": " + pct(x[1]));
      add(tr, h("div", "fill")).style.width = pct(x[1]); add(r, h("span", "pct", pct(x[1])));
    });
    var hm = clear($("h-more"));
    dl(hm, [["Basis", H.basis + "; mean " + H.share_other_regarding.toFixed(2) + " (SD " + H.share_other_regarding_sd.toFixed(2) + ")"],
            ["S2 Table value", H.s2_table_share_other_regarding.toFixed(2)],
            ["How altruistic each response was rated", "other-regarding option " + H.rating_other_option.toFixed(2) + ", self-regarding option " + H.rating_self_option.toFixed(2) + " (" + H.rating_basis + ")"],
            ["Closeness and realism ratings", H.social_closeness_rating.toFixed(2) + " and " + H.similarity_to_reality_rating.toFixed(2) + " (1 to 7)"],
            ["Note", H.notes.join(" ")]]);

    var S = it.screening, e = ELIG[it.eligibility];
    var sk = $("s-kind"); sk.className = "kind " + e[0]; sk.textContent = e[1];
    $("s-kind").parentNode.className = "card pad blk" + (it.eligibility === "stress_test" ? " blk-stress" : "");
    var sd = clear($("s-dl"));
    dl(sd, [["Status", S.status === "selected" ? "Selected at screening (core set)" : S.status === "reserve" ? "Reserve" : "Excluded"],
            ["Decided at", "step " + S.step + ": " + ruleText(S.step)],
            ["Flags", S.flags.length ? S.flags.map(function (f) { return f + " " + L.flag_definitions[f]; }).join("; ") : "none"],
            ["Reason (our coding)", S.reason], ["Eligibility for our test", it.eligibility_note],
            ["Value conflict", it.value_conflict.label + (it.value_conflict.extra_elements.length ? "; also involves: " + it.value_conflict.extra_elements.join(", ") : "")],
            ["Coded by", S.coded_by]]);

    drawAdaptation(it); drawConds(); drawModels(it); drawInspect(it);
    if (focus) { $("d-h").focus(); $("detail").scrollIntoView(); }
  }
  function ruleText(step) { var r = L.selection_rule.filter(function (x) { return x[0] === step; })[0]; return r ? r[1] : ""; }

  function drawAdaptation(it) {
    var box = clear($("a-body")), a = it.adaptation;
    if (!a) { add(box, h("p", "small muted", "No adaptation: this item is excluded from the matched-priority test (" + it.eligibility_note + ")")); return; }
    if (!a.built) { add(box, h("p", "small muted", a.note)); return; }
    add(box, h("p", "small", "The verbatim scenario is followed by “" + a.task_suffix.trim() + "” The options are labelled A and B, in both orders. Scenario change: " + a.scenario_change + "."));
    var od = add(box, h("div", "orders"));
    [["orig", "Order 1"], ["swap", "Order 2"]].forEach(function (k) {
      var c = add(od, h("div")); add(c, h("span", "k", k[1]));
      ["A", "B"].forEach(function (l) { var x = add(c, h("div", "optc")); add(x, h("b", null, l)); add(x, document.createTextNode(a.orders[k[0]][l])); });
    });
    [["other", "Priority favouring the other-regarding option"], ["self", "Priority favouring the self-regarding option"]].forEach(function (k) {
      var p = add(box, h("div", "prio")); add(p, h("span", "k", k[1])); add(p, document.createTextNode("“" + a.priorities[k[0]] + "”"));
    });
    add(box, h("p", "fine", a.expected_note + " " + a.n_cases + " cases: 2 priorities × 2 option orders."));
    if (a.item_checks.length) { add(box, h("p", "k", "Item-specific checks")); var ul = add(box, h("ul", "small")); a.item_checks.forEach(function (c) { add(ul, h("li", null, c)); }); }
    add(box, h("p", "fine", L.adaptation_status));
  }

  function drawConds() {
    var g = clear($("conds"));
    L.design.conditions.forEach(function (c) {
      var d = add(g, h("div", "cond")); add(d, h("span", "k", c.code + " · " + (c.kind === "priority" ? "both priorities, both orders" : "no priority, both orders")));
      add(d, h("b", null, c.name)); add(d, h("p", "small muted", "The final decision receives: " + c.prompt + "."));
    });
    $("design-status").textContent = L.design.case_count + "; " + L.design.calls + " calls in all; " + L.design.repetition + ". " + L.design.status;
  }

  var OPTCLASS = { other_regarding_option: "other-regarding option", self_regarding_option: "self-regarding option" };
  var FILES = {}; (L.results.files || []).forEach(function (f) { FILES[f.model_id] = f; });
  // Plain-text ledger reference (no link): unit, attempt and the first 12 hex of the raw record's sha256.
  function refText(ref) { return ref && ref.raw_sha256 ? ref.unit_id + " · attempt " + ref.attempt + " · raw sha256 " + ref.raw_sha256.slice(0, 12) + "…" : (ref ? ref.unit_id + " · no completed call" : ""); }
  function cellText(r) {
    if (r.status === "missing") return "Missing (call failed)";
    if (r.status !== "recorded") return "Not yet tested";
    return "Recorded: " + r.choice + (OPTCLASS[r.option_class] ? ", " + OPTCLASS[r.option_class] : "") + " (" + r.outcome.replace("_", " ") + ")";
  }
  function runLine(m) {
    var f = FILES[m.id];
    return f ? (f.fake_transport ? "FAKE TRANSPORT TEST DATA, NOT EVIDENCE. " : "") + "Recorded run " + f.run_id + " · ledger head " + f.ledger_head_sha256.slice(0, 12) + "… · " +
               f.n_records + " cells, " + f.n_missing + " missing." : m.plan;
  }

  function drawModels(it) {
    $("m-note").textContent = L.results.note + " Each cell shows the status of one final decision for this dilemma. " +
      "These panels are the exploratory three-model Singer experiment, one panel per model; the Gemini 2.5 Pro results elsewhere on this site are a different, earlier pilot and are not shown or combined here. " +
      (it.eligibility === "planned" ? "" : "This dilemma is not in the planned test set, so no run is scheduled for it.");
    var box = clear($("models"));
    L.models.forEach(function (m) {
      var c = add(box, h("article", "card mcard")); c.setAttribute("data-model", m.id);
      add(c, h("span", "k exp", m.experiment));
      add(c, h("h3", null, m.label)); add(c, h("p", "fine pin", "Pinned model: " + m.pinned_id));
      add(c, h("p", "plan", runLine(m)));
      L.design.conditions.forEach(function (cd) {
        var row = add(c, h("div", "mrow")); add(row, h("span", "k", cd.code + " · " + cd.name));
        var ul = add(row, h("ul", "mcells"));
        cd.cells.forEach(function (k) {
          var r = it.ai[m.id][cd.code][k], li = add(ul, h("li", "mcell")); li.setAttribute("data-status", r.status);
          add(li, h("b", null, CELL[k]));
          add(li, h("span", "v", cellText(r)));
          if (r.status === "recorded") add(li, h("span", "s", " · served " + r.served_model_version + " · ledger " + refText(r.ledger_ref)));
          if (r.status === "missing" && r.missing_reason) add(li, h("span", "s", " · " + r.missing_reason));
        });
      });
    });
  }

  function drawInspect(it) {
    var ms = clear($("x-model")), cs = clear($("x-cond")), ks = $("x-cell");
    L.models.forEach(function (m) { add(ms, h("option", null, m.label)).value = m.id; });
    L.design.conditions.filter(function (c) { return c.chain; }).forEach(function (c) { add(cs, h("option", null, c.code + " · " + c.name)).value = c.code; });
    function cells() {
      var c = L.design.conditions.filter(function (x) { return x.code === cs.value; })[0], keep = ks.value; clear(ks);
      c.cells.forEach(function (k) { add(ks, h("option", null, CELL[k])).value = k; });
      if (c.cells.indexOf(keep) >= 0) ks.value = keep;
    }
    function show() {
      var r = it.ai[ms.value][cs.value][ks.value], out = clear($("x-out")), box = add(out, h("div", "chainbox"));
      var m = L.models.filter(function (x) { return x.id === ms.value; })[0];
      if (r.status === "recorded" || r.status === "missing") {
        if (FILES[m.id] && FILES[m.id].fake_transport) add(box, h("p", "small", "FAKE TRANSPORT TEST DATA, NOT EVIDENCE."));
        add(box, h("span", "kind " + (r.status === "recorded" ? "kind-rec" : "kind-none"), r.status === "recorded" ? "Recorded" : "Missing (call failed)"));
        add(box, h("p", "fine", m.label + " only (" + m.experiment + "). Run " + FILES[m.id].run_id + "."));
        if (r.handoffs) {
          var ol = add(box, h("ol")); ol.className = "handoffs";
          r.handoffs.forEach(function (t, i) {
            var li = add(ol, h("li")); add(li, h("b", null, "Handoff " + (i + 1) + ": ")); add(li, document.createTextNode(t));
            var hr = r.handoff_refs && r.handoff_refs[i];
            if (hr) add(li, h("span", "fine", " (served " + hr.served_model_version + " · ledger " + refText(hr.ledger_ref) + ")"));
          });
        } else {
          add(box, h("p", "small", "No complete six-handoff chain was recorded for this cell."));
        }
        add(box, h("p", "small", r.status === "recorded"
          ? "Final choice: " + cellText(r).replace("Recorded: ", "") + ". Served model: " + r.served_model_version + ". Ledger: " + refText(r.ledger_ref)
          : "Final choice: missing (call failed" + (r.missing_reason ? ": " + r.missing_reason : "") + "). Ledger: " + refText(r.ledger_ref)));
      } else {
        add(box, h("span", "kind kind-none", "Not yet tested")); add(box, h("p", "small", "No recorded chain yet."));
        add(box, h("p", "fine", "When a verified run exists, the six handoffs and the final choice for this model, workflow, priority and order will appear here, from the run ledger only."));
      }
    }
    ms.onchange = show; cs.onchange = function () { cells(); show(); }; ks.onchange = show;
    cells(); show();
  }

  // ---------------------------------------------------------------- sources, rule, pilot
  var sb = $("sources");
  L.other_sources.forEach(function (s) {
    var c = add(sb, h("article", "card srccard")); c.setAttribute("data-source", s.id);
    add(c, h("span", "kind " + (s.verdict === "cite only" ? "kind-none" : "kind-ours"), s.verdict === "cite only" ? "Cite only" : "Adaptable · pending, not used"));
    add(c, h("h3", null, s.short)); var p = add(c, h("p")); add(p, document.createTextNode(s.citation + " ")); add(p, link(s.doi_url, s.doi_url));
    add(c, h("p", null, "Fit for a two-option test: " + s.paired_priority_suitability));
    var lic = add(c, h("p")); add(lic, document.createTextNode("Licence: " + s.licence.article.licence + ". "));
    add(lic, link(s.licence.article.evidence_url, "Licence evidence")); add(lic, document.createTextNode(" (checked " + s.licence.article.accessed + ")."));
    add(c, h("p", "fine", s.verdict_note));
  });
  var rl = $("rule"); L.selection_rule.forEach(function (r) { add(rl, h("li", null, r[0] + ": " + r[1])); });
  $("topic-note").textContent = L.topic_note;

  drawChips(); drawList();
  var hid = location.hash.slice(1);
  if (BY[hid]) open(hid, false);
  window.addEventListener("hashchange", function () { var x = location.hash.slice(1); if (BY[x] && x !== st.sel) open(x, true); });
})();
